#pragma once#define SET_WND 0x01#ifdef __MAIN_FILE__//UINT nSensorsKeyboard = ::RegisterWindowMessageA("Сенсорная Клавиатура");UINT nMessageKeyboard = ::RegisterWindowMessageA("Внешняя Клавиатура");//char szClassNameCOM1[] =  "Keyboard COM1";BOOL IsKeyCOM1( HWND& hWnd )  {  static HWND gs_hWnd;  if ( !::IsWindow( gs_hWnd ) )  gs_hWnd = ::FindWindow(szClassNameCOM1,NULL);  hWnd = gs_hWnd;	return ::IsWindow(hWnd);  }//char szClassNameUSB[] =  "Keyboard USB";BOOL IsKeyUSB( HWND& hWnd )  {  static HWND gs_hWnd;  if ( !::IsWindow( gs_hWnd ) )  gs_hWnd = ::FindWindow(szClassNameUSB,NULL);  hWnd = gs_hWnd;	return ::IsWindow(hWnd);  }//char szClassNameSensor[] =  "Keyboard Sensor";BOOL IsNewSensor( void )  {  if ( (Version==PET_UFA) ||(Version==KC_2_NV)||(Version==PHU_2_NV)||(Version==TU_4_NV)||(Version==DKS_NV)||(Version==KC_3_NV)||(Version==BITUM_MSK)||(Version==PSA_MSK)||(Version==PP_TSK)||(Version==MAU_3_NV)||(Version==MAU_4_NV)||(Version==UPG_1_BZ)||(Version==UPG_2_BZ)||(Version==C300_YAR)||(Version==C400_YAR)||(Version==C500_YAR)||(Version==LG35_8_KF)||(Version==H2_TSK)||(Version==TEA_TSK)||(Version==LAB_KF)||(Version==UPO_KF)||(Version==UCGIK_NTK_UBGPZ)||(Version==DKS_NTKR_UBGPZ)||(Version==UPG_UBGPZ)||(Version==UGOSH_UBGPZ)||(Version==UNU_DZ)||(Version==AK_DZ)||(Version==C8H8_PM)||(Version==_2104_NKNH)||(Version==_2106_NKNH)||(Version==BK2_TBK)||(Version==BK2_1_TBK)||(Version==M_2_TBK)||(Version==BK8_10_1_TBK)||(Version==BK8_1_10_2_TBK)||(Version==DOTF_PM)||(Version==B6_9_TBK)||(Version==B3_TBK)||(Version==B3_2_TBK)||(Version==B1_2_TBK)||(Version==_36_3_OZSM)||(Version==_37_1_OZSM)||(Version==GB_201_NKNH)||(Version==NTGR_NKNH)||(Version==VTGR_NKNH)||(Version==REF_C_NKNH)||(Version==L35_6_YAR)||(Version==_1510_NKNH)||(Version==UREA_BRZK)||(Version==L35_11600_KF)||(Version==H2SO4_YAR)||(Version==GFU_YAR)||(Version==ROSK_YAR)||(Version==AM2_NAK)||(Version==DMW_NAK)||(Version>=L35_11_1000_KF))	  return TRUE;  return FALSE;  }BOOL IsKeySensor( HWND& hWnd )  {  if ((Version==NH3_KEM)||(Version==PPF_POM)||(Version==CPP_POM)||(Version==DBO10_TOBOLSK)||      (Version==AOP_TOBOLSK)||(Version==GF_2_TOBOLSK)||(Version==MK2_YAR)||IsNewSensor())	  return true;  static HWND gs_hWnd;  if ( !::IsWindow( gs_hWnd ) )  gs_hWnd = ::FindWindow(szClassNameSensor,NULL);  hWnd = gs_hWnd;	return ::IsWindow(hWnd);  }////#else//extern UINT nSensorsKeyboard;extern UINT nMessageKeyboard;extern char szClassNameCOM1[];extern BOOL IsKeyCOM1( HWND& hWnd );extern char szClassNameUSB[];extern BOOL IsKeyUSB( HWND& hWnd );extern char szClassNameSensor[];extern BOOL IsKeySensor( HWND& hWnd );extern BOOL IsNewSensor( void );//#endif#define  MessageCOM1( hWnd, wParam )  SendMessage( hWnd, nMessageKeyboard, wParam, 0 )#define  MessageUSB( hWnd, wParam )  SendMessage( hWnd, nMessageKeyboard, wParam, 0 )// Период мерцания#define INDICATOR_OFF       0x01 // Не горит#define INDICATOR_ON        0x02 // Горит постоянно#define INDICATOR_BLINKFAST 0x03 // Мерцает 500  ms#define INDICATOR_BLINKSLOW 0x04 // Мерцает 1000 ms// INDICATORS#define FAST_INDICATOR  0xFB#define ALPHA_INDICATOR 0xF7//#define KEY_DOWN_CODE			0x80	#define KEY_UP_CODE				0xf0//#define  PostSensor( hWnd, wParam, lParam )  PostMessage( hWnd, nSensorsKeyboard, wParam, (LPARAM)lParam )